58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
64	
65	    private final ClinicService clinicService;
66	
67	    private final OwnerMapper ownerMapper;
68	
69	    private final PetMapper petMapper;
70	
71	    private final VisitMapper visitMapper;
72	
73	    public OwnerRestControllerV1(ClinicService clinicService,
74	                                 OwnerMapper ownerMapper,
75	                                 PetMapper petMapper,
76	                                 VisitMapper visitMapper) {
77	        this.clinicService = clinicService;
78	        this.ownerMapper = ownerMapper;
79	        this.petMapper = petMapper;
80	        this.visitMapper = visitMapper;
81	    }
82	
83	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
84	    @Override
85	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
86	        Collection<Owner> owners;
87	        if (lastName != null) {
88	            owners = this.clinicService.findOwnerByLastName(lastName);
89	        } else {
90	            owners = this.clinicService.findAllOwners();
91	        }
92	        if (owners.isEmpty()) {
93	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
94	        }
95	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
101	        Owner owner = this.clinicService.findOwnerById(ownerId);
102	        if (owner == null) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
111	        HttpHeaders headers = new HttpHeaders();
112	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
113	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
114	        owner.setTelephone(normalizedTelephone);
115	        owner.setEmail(normalizeEmail(owner.getEmail()));
116	        owner.setAddress(normalizeAddress(owner.getAddress()));
117	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
118	        if (effectiveRegistrationDate == null) {
119	            effectiveRegistrationDate = LocalDate.now();
120	        }
121	        effectiveRegistrationDate = rollToBusinessDay(effectiveRegistrationDate);
122	        owner.setRegistrationDate(effectiveRegistrationDate);
123	        if (countOwnersRegisteredOn(effectiveRegistrationDate) >= DAILY_CREATE_LIMIT) {
124	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
125	                "the maximum number of owners that may be created today has been reached");
126	        }
127	        if (isTelephoneInUse(normalizedTelephone, null)) {
128	            throw new ResponseStatusException(HttpStatus.CONFLICT,
129	                "telephone is already in use by another owner");
130	        }
131	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
132	        if (!sharesHousehold
133	            && this.clinicService.isHouseholdInUse(owner.getLastName(), owner.getAddress(), null)) {
134	            throw new ResponseStatusException(HttpStatus.CONFLICT,
135	                "another owner with the same last name already lives at this address");
136	        }
137	        if (countOwnersInCity(owner.getCity()) >= CITY_CAPACITY) {
138	            throw new ResponseStatusException(HttpStatus.CONFLICT,
139	                "city has reached its maximum number of owners");
140	        }
141	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
142	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
143	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
144	        if (sharesHousehold) {
145	            this.clinicService.assignHousehold(owner);
146	        }
147	        this.clinicService.saveOwner(owner);
148	        AUDIT.info("owner created: id={} customerCode={} registrationDate={}",
149	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
150	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
151	        headers.setLocation(UriComponentsBuilder.newInstance()
152	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
153	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Override
158	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
159	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
160	        if (currentOwner == null) {
161	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
162	        }
163	        currentOwner.setAddress(ownerFieldsDto.getAddress());
164	        currentOwner.setCity(ownerFieldsDto.getCity());
165	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
166	        currentOwner.setLastName(ownerFieldsDto.getLastName());
167	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
168	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
169	        this.clinicService.saveOwner(currentOwner);
170	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
171	    }
172	
173	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
174	    @Transactional
175	    @Override
176	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
177	        Owner owner = this.clinicService.findOwnerById(ownerId);
178	        if (owner == null) {
179	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
180	        }
181	        this.clinicService.deleteOwner(owner);
182	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
183	    }
184	
185	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
186	    @Override
187	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
188	        Owner owner = this.clinicService.findOwnerById(ownerId);
189	        if (owner == null) {
190	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
191	        }
192	        HttpHeaders headers = new HttpHeaders();
193	        Pet pet = petMapper.toPet(petFieldsDto);
194	        owner.setId(ownerId);
195	        pet.setOwner(owner);
196	        pet.getType().setName(null);
197	        this.clinicService.savePet(pet);
198	        PetDto petDto = petMapper.toPetDto(pet);
199	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
200	            .buildAndExpand(pet.getId()).toUri());
201	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
202	    }
203	
204	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
205	    @Override
206	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
207	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
208	        if (currentOwner != null) {
209	            Pet currentPet = this.clinicService.findPetById(petId);
210	            if (currentPet != null) {
211	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
212	                currentPet.setName(petFieldsDto.getName());
213	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
214	                this.clinicService.savePet(currentPet);
215	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
216	            }
217	        }
218	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
219	    }
220	
221	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
222	    @Override
223	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
224	        HttpHeaders headers = new HttpHeaders();
225	        Visit visit = visitMapper.toVisit(visitFieldsDto);
226	        Pet pet = new Pet();
227	        pet.setId(petId);
228	        visit.setPet(pet);
229	        this.clinicService.saveVisit(visit);
230	        VisitDto visitDto = visitMapper.toVisitDto(visit);
231	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
232	            .buildAndExpand(visit.getId()).toUri());
233	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
234	    }
235	
236	
237	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
238	    @Override
239	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
240	        Owner owner = this.clinicService.findOwnerById(ownerId);
241	        if (owner != null) {
242	            Pet pet = owner.getPet(petId);
243	            if (pet != null) {
244	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
245	            }
246	        }
247	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
248	    }
249	
250	    /**
251	     * Builds the customer code for a new owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is
252	     * the upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
253	     * last name, and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
254	     * owners that already live in that city (e.g. {@code 'LON-SMI-0007'}).
255	     *
256	     * @param city     the owner's city
257	     * @param lastName the owner's last name
258	     * @return the assigned customer code
259	     */
260	    private String nextCustomerCode(String city, String lastName) {
261	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
262	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
263	        int sequence = countOwnersInCity(city) + 1;
264	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
265	    }
266	
267	    /**
268	     * The maximum number of owners allowed to live in a single city. A create is rejected once the
269	     * owner's city already contains this many owners.
270	     */
271	    private static final int CITY_CAPACITY = 50;
272	
273	    /**
274	     * The maximum number of owners that may be created on a single day. A create is rejected with
275	     * {@link HttpStatus#TOO_MANY_REQUESTS} once this many owners already have today's
276	     * {@code registrationDate}.
277	     */
278	    private static final int DAILY_CREATE_LIMIT = 100;
279	
280	    /**
281	     * Rolls a registration date forward onto a business day: a date that falls on a Saturday or
282	     * Sunday is moved forward to the following Monday, while a date already on a weekday is returned
283	     * unchanged. Applied to the effective registration date (supplied or defaulted to the server
284	     * date) so that the stored {@code registrationDate}, and every value derived from it, always
285	     * falls on a business day.
286	     *
287	     * @param date the effective registration date
288	     * @return the same date when it is a weekday, otherwise the following Monday
289	     */
290	    private static LocalDate rollToBusinessDay(LocalDate date) {
291	        return switch (date.getDayOfWeek()) {
292	            case SATURDAY -> date.plusDays(2);
293	            case SUNDAY -> date.plusDays(1);
294	            default -> date;
295	        };
296	    }
297	
298	    /**
299	     * Counts the existing owners whose {@code registrationDate} equals the given (already
300	     * business-day-adjusted) date, i.e. the number of owners that have already been created for that
301	     * business day. Called before a new owner is saved, so the returned value reflects the number of
302	     * owners created for that day prior to this create.
303	     *
304	     * @param date the adjusted business-day registration date to count against
305	     * @return the number of existing owners registered on that date
306	     */
307	    private int countOwnersRegisteredOn(LocalDate date) {
308	        return (int) this.clinicService.findAllOwners().stream()
309	            .filter(existing -> date.equals(existing.getRegistrationDate()))
310	            .count();
311	    }
312	
313	    /**
314	     * Counts the existing owners that live in the given city, comparing city names case-insensitively.
315	     *
316	     * @param city the city to count owners for
317	     * @return the number of existing owners in that city
318	     */
319	    private int countOwnersInCity(String city) {
320	        return (int) this.clinicService.findAllOwners().stream()
321	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
322	            .count();
323	    }
324	
325	    /**
326	     * Builds the membership number for a new owner, formatted {@code '<customerCode>-M<YY>'} where YY is
327	     * the last two digits of the registration date's year (e.g. {@code 'LON-SMI-0007-M26'}).
328	     *
329	     * @param customerCode     the owner's assigned customer code
330	     * @param registrationDate the owner's registration date
331	     * @return the assigned membership number
332	     */
333	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
334	        String yy = String.format("%02d", registrationDate.getYear() % 100);
335	        return String.format("%s-M%s", customerCode, yy);
336	    }
337	
338	    /**
339	     * Counts the existing owners that already share the given first name and last name, comparing
340	     * both case-insensitively. Called before a new owner is saved, so the returned value reflects
341	     * the number of namesakes that existed prior to this create.
342	     *
343	     * @param firstName the new owner's first name
344	     * @param lastName  the new owner's last name
345	     * @return the number of existing owners with the same first and last name
346	     */
347	    private int countNamesakes(String firstName, String lastName) {
348	        int count = 0;
349	        for (Owner existing : this.clinicService.findAllOwners()) {
350	            if (firstName.equalsIgnoreCase(existing.getFirstName())
351	                && lastName.equalsIgnoreCase(existing.getLastName())) {
352	                count++;
353	            }
354	        }
355	        return count;
356	    }
357	
358	    /**
359	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
360	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
361	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
362	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
363	     * string is what gets stored and returned.
364	     *
365	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
366	     *
367	     * @param telephone the raw telephone value supplied by the client
368	     * @return the normalized E.164 telephone number
369	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
370	     *                                 valid E.164 number (unexpected characters, or not 8 to 15
371	     *                                 digits after the {@code '+'})
372	     */
373	    private static String normalizeTelephone(String telephone) {
374	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
375	        String digits;
376	        if (cleaned.startsWith("+")) {
377	            digits = cleaned.substring(1);
378	        } else {
379	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
380	            digits = "61" + national;
381	        }
382	        if (!digits.matches("[0-9]{8,15}")) {
383	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
384	                "telephone could not be normalized to a valid E.164 number");
385	        }
386	        return "+" + digits;
387	    }
388	
389	    /**
390	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, falling back
391	     * to the raw stored value if it cannot be normalized (e.g. legacy seed data in another format).
392	     *
393	     * @param telephone the stored telephone value, possibly {@code null}
394	     * @return the E.164 form, or the raw value when it cannot be normalized
395	     */
396	    private static String toComparableTelephone(String telephone) {
397	        try {
398	            return normalizeTelephone(telephone);
399	        } catch (ResponseStatusException ex) {
400	            return telephone;
401	        }
402	    }
403	
404	    /**
405	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
406	     * containing at least one dot, none of the three sections containing whitespace or an
407	     * additional {@code @}.
408	     */
409	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
410	
411	    /**
412	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
413	     * (email is optional). When a value is supplied it must be a syntactically valid address; the
414	     * value is then stored and returned lower-cased.
415	     *
416	     * @param email the raw email value supplied by the client, possibly {@code null}
417	     * @return the lower-cased email, or {@code null} when none was supplied
418	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
419	     *                                 is not a syntactically valid address
420	     */
421	    private static String normalizeEmail(String email) {
422	        if (email == null) {
423	            return null;
424	        }
425	        if (!EMAIL_PATTERN.matcher(email).matches()) {
426	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
427	                "email must be a syntactically valid address");
428	        }
429	        return email.toLowerCase(Locale.ROOT);
430	    }
431	
432	    /**
433	     * Common street-type abbreviations expanded to their full word during address normalization.
434	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
435	     */
436	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
437	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
438	
439	    /**
440	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
441	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
442	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
443	     * {@code AVE -> AVENUE}). This normalized value is what gets stored, returned, and used for every
444	     * address comparison (household duplicate detection and the shared household id).
445	     *
446	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
447	     *
448	     * @param address the raw address supplied by the client, possibly {@code null}
449	     * @return the normalized address
450	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
451	     *                                 after normalization (required field)
452	     */
453	    private static String normalizeAddress(String address) {
454	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
455	        if (collapsed.isEmpty()) {
456	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
457	                "address must not be blank");
458	        }
459	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
460	        StringBuilder normalized = new StringBuilder();
461	        for (int i = 0; i < tokens.length; i++) {
462	            if (i > 0) {
463	                normalized.append(' ');
464	            }
465	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
466	        }
467	        return normalized.toString();
468	    }
469	
470	    /**
471	     * Determines whether the given normalized E.164 telephone is already used by any owner other
472	     * than the one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g.
473	     * on create). Stored telephones are compared by their E.164 value so that differently formatted
474	     * inputs representing the same number are treated as duplicates.
475	     *
476	     * @param normalizedTelephone the already-normalized E.164 telephone to look for
477	     * @param excludeId           id of an owner to ignore during the check, or {@code null} for none
478	     * @return {@code true} if another owner already uses the telephone
479	     */
480	    private boolean isTelephoneInUse(String normalizedTelephone, Integer excludeId) {
481	        for (Owner existing : this.clinicService.findAllOwners()) {
482	            if (excludeId != null && excludeId.equals(existing.getId())) {
483	                continue;
484	            }
485	            if (normalizedTelephone.equals(toComparableTelephone(existing.getTelephone()))) {
486	                return true;
487	            }
488	        }
489	        return false;
490	    }
491	
492	}
